def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-6, atol: float = 1e-9):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(1)
n_ep = 24
n_ch = 4
n_t = 40
X = rng.randn(n_ep, n_ch, n_t)
y = np.array([1, 2] * 12)
tt = np.arange(n_t).astype(float)
for e in range(n_ep):
    if y[e] == 1:
        X[e, 0] += 3 * np.sin(tt / 4.)
    else:
        X[e, 1] += 2 * np.cos(tt / 5.)
events = np.zeros((n_ep, 3), int)
for e in range(n_ep):
    events[e, 0] = e * 100
    events[e, 2] = y[e]
info = mne.create_info(n_ch, 100., 'eeg')
ep = mne.EpochsArray(X, info, events, tmin=0., event_id={'a': 1, 'b': 2})
xd = Xdawn(n_components=2).fit(ep)
check("xd_filters_a", [np.abs(xd.filters_['a'])])
check("xd_patterns_b", [np.abs(xd.patterns_['b'])])
check("xd_transform", [np.abs(xd.transform(ep)[3, :, :5])])
ap = xd.apply(ep)
check("xd_apply_a", [ap['a'].get_data()[2, :, :5]])
events2 = events.copy()
for e in range(n_ep):
    events2[e, 0] = e * 30
ep2 = mne.EpochsArray(X, info, events2, tmin=0., event_id={'a': 1, 'b': 2})
xd2 = Xdawn(n_components=1, reg=0.1).fit(ep2)
check("xd2_overlap", [float(xd2.correct_overlap_)])
check("xd2_filters_b", [np.abs(xd2.filters_['b'])])

ph = rng.rand(10, 2, 30)
ks, pk, _ = ctps(ph, is_raw=False)
check("ctps_ks", [ks[:, :6]])
check("ctps_pk", [pk[:, :6]])
x3 = rng.randn(12, 2, 64)
for e in range(12):
    x3[e, 0] += np.sin(np.arange(64) / 3.)
ks, pk, _ = ctps(x3)
check("ctps_raw_pk", [pk[:, ::8]])

sf = 250.
n = 5000
rng = np.random.RandomState(3)
ecg = np.zeros(n)
for c in range(100, n, 227):
    ecg += np.exp(-0.5 * ((np.arange(n) - c) / 3.) ** 2)
ecg += 0.02 * rng.randn(n)
mix = rng.randn(3, 2)
eeg = mix @ np.vstack([ecg, rng.randn(n)]) * 1e-5 + rng.randn(3, n) * 1e-6
d2 = np.vstack([eeg, ecg.reshape((1, n)) * 1e-4])
raw2 = mne.io.RawArray(d2, mne.create_info(['A', 'B', 'C', 'ECG'], sf, ['eeg', 'eeg', 'eeg', 'ecg']))
ee = create_ecg_epochs(raw2, tmin=-0.2, tmax=0.2)
check("ecg_epochs_shape", [float(v) for v in ee.get_data().shape])
check("ecg_epochs_events", [ee.events[:, 0]])
check("ecg_epochs_val", [ee.get_data()[1, :, 50]], 1e-9, 1e-15)
ica = ICA(n_components=2, random_state=0).fit(raw2)
inds, scores = ica.find_bads_ecg(raw2)
check("ctps_inds", inds)
check("ctps_scores", scores, 1e-4, 1e-6)
